def count_divisors(num):
    count = 0
    for i in range(1, int(num**0.5) + 1):
        if num % i == 0:
            count += 1
            if i * i != num:
                count += 1
    return count

max_divisors = -1
hcn_list = []
LIMIT = 150000 # Increasing limit to ensure 50 HCNs are captured

for i in range(1, LIMIT + 1):
