import math

def tau(n):
    if n <= 0:
        return 0
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

# List of the first few Highly Composite Numbers (HCNs)
# Based on known sequences, we test a reasonable range.
# HCNs: 1, 2, 4, 6, 12, 24, 36, 48, 60, 120, 180, 240, 360, 720, ...
# We start from F=2 as per problem statement (F >= 2).
hcn_candidates = [
    2, 4, 6, 12, 24, 36, 48, 60, 120, 180, 240, 360, 720, 840, 1260, 1680
]

def score_F(F):
    if F < 2: return 0
    return tau(F) * tau(F - 1) * tau(F + 1)

# Calculate scores for the candidates
scored_hcn = {}
for F in hcn_candidates:
    scored_hcn[F] = score_F(F)

# Sort by score in descending order
sorted_hcn = sorted(scored_hcn.items(), key=lambda item: item[1], reverse=True)

# Get the top 5 candidates
top_5_candidates = [item[0] for item in sorted_hcn[:5]]

print(f"Top 5 Candidates F (HCNs maximizing tau(F) * tau(F-1) * tau(F+1)): {top_5_candidates}")
print(f"Scores for these 5 candidates: {[scored_hcn[f] for f in top_5_candidates]}")
